rows=[]
def add(school,metric,value,season,src,url,note,unit=None):
    unit=unit or ('USD' if metric.endswith('_value') else 'years' if metric.endswith('term_years') else 'year' if metric.endswith('_year') else 'text')
    rows.append([school,metric,value,unit,season,src,url,D,note])
