done={(r[0],r[1]) for r in rows}
pat=re.compile(r'budget|research effort|exhaust',re.I)
n=0
for d,schools in SEARCHED.items():
    for s,why in schools.items():
        for m in ('annual_value','total_value','term_years','start_year'):
            k=(s,f'{d}_{m}')
            if k in done: continue
            cur=V.get(k)
            if cur is None or cur['value'] not in ('--',''): continue
            if not pat.search(cur['notes']): continue        # leave cells that already carry a specific reason
            add(s,k[1],'--','2026','searched 17 Nov 2026','',f"Searched on 17 Nov 2026 and not found: {why}."); n+=1
with open('data/research/verification_zzzzzzzz_deal_terms.csv','w',newline='',encoding='utf-8') as fh:
    w=csv.writer(fh); w.writerow(['school','metric','value','unit','fiscal_year_or_season','source_name','source_url','date_accessed','notes']); w.writerows(rows)
print('rows',len(rows),'| value rows',sum(1 for r in rows if r[2]!='--'),'| reason rows',n)
